    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    objects = []

    # Connected components of each nonzero color
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            objects.append((color,r0,r1,c0,c1,cells))

    # Identify rectangular frames (one-color complete border).
    frames = []
    for color,r0,r1,c0,c1,cells in objects:
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if (all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0,c1+1)) and
            all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0,r1+1))):
