                   for y in range(r0+1,r1)]
            frames.append((color,r0,r1,c0,c1,pat))

    # The patterned frame is the source. Copy its pattern only to frames
    # with matching outer dimensions; other frames are removed.
    source = max(frames, key=lambda f: sum(map(sum,f[5]))) if frames else None
    if source:
        sc,sr0,sr1,sc0,sc1,pat = source
        sh,sw = len(pat),len(pat[0])
        for color,r0,r1,c0,c1,_ in frames:
            if color == sc:
                continue
